+//! Raw bindings that are a module of the scanned crate, not a `-sys` crate: named to the
+//! scan as `crate::raw`, they join the inventory `cells-sys` gives.
+//!
+//! ty.ffibox.sys.total, of_which.raw_ptr_in_sys (`raw_local`, behind `local_get`'s
+//! pointer); fn.ffibox.sys.total twice (`local_get`, `nope`). `nope` is the name
+//! `value_or`'s second alias gives: fn.ffibox.wrapper.non_trait, of_which.unique.
+
+#[repr(C)]
+pub struct raw_local {
+    pub n: i32,
+}
+
+unsafe extern "C" {
+    pub fn local_get(l: *mut raw_local) -> i32;
+    pub fn nope() -> i32;
+}
diff --git a/tests/test_cells.py b/tests/test_cells.py
index 6b138d7..f647218 100644
--- a/tests/test_cells.py
+++ b/tests/test_cells.py
@@ -257,6 +257,33 @@ class CellCounterTests(unittest.TestCase):
         # The accessors are no cells: the wrapper count stays the cells'.
         self.assertEqual(self.at("ty.ffibox.wrapper.total"), 1)

+    def test_a_module_of_the_crate_joins_the_inventory_when_named(self) -> None:
+        """`cells`' own `raw` module holds raw bindings: one struct, behind a
+        pointer of one of its two fns. Named as `crate::raw`, it joins what
+        `cells-sys` gives; unnamed, as in every other test here, it counts
+        nowhere. `value_or`'s alias `nope` then names one of its fns."""
+        both = scan.compose(FIXTURE, ffibox=True, sys_crates=[*SYS, "crate::raw"])
+        self.assertEqual(both["sys_crates"], ["cells_sys", "crate::raw"])
+        tree = both["counts"]
+
+        def at(key: str) -> int:
+            node = tree
+            for part in key.split("."):
+                node = node[part]
+            return node if isinstance(node, int) else node["total"]
+
+        def delta(key: str) -> int:
+            return at(key) - self.at(key)
+        self.assertEqual(delta("ty.ffibox.sys.total"), 1)
+        self.assertEqual(delta("ty.ffibox.sys.of_which.raw_ptr_in_sys.total"), 1)
+        self.assertEqual(delta("fn.ffibox.sys.total"), 2)
+        self.assertEqual(delta("fn.ffibox.wrapper.total"), 1)
+        self.assertEqual(delta("fn.ffibox.wrapper.non_trait"), 1)
+        self.assertEqual(delta("fn.ffibox.wrapper.of_which.unique"), 1)
+        alone = scan.compose(FIXTURE, ffibox=True, sys_crates=["crate::raw"])["counts"]
+        self.assertEqual(alone["ty"]["ffibox"]["sys"]["total"], 1)
+        self.assertEqual(alone["fn"]["ffibox"]["sys"]["total"], 2)
+
     def test_the_sys_inventory_needs_the_crates_named(self) -> None:
         """Without `--sys-crates` there is no inventory to take, so the counts
         are absent rather than zero; the mentions stay."""

