/// The methods by which an ffibox primitive hands its pointer to C.
const FFIBOX_SURRENDERERS: &[&str] = &["into_raw", "into_c", "into_raw_parts"];

/// The std traits whose impls on a crate's own types are counted one by one,
/// as `ty.total.of_which.std_impl.<trait>`: the ones a Rust consumer expects of
/// a value, which C's conventions have no counterpart for. A fixed list, so
/// the breakdown is a closed set the registry carries.
const STD_IDIOM_TRAITS: &[&str] = &[
    "Debug", "Display", "Error", "Clone", "Default", "PartialEq", "Eq", "Hash",
    "Iterator", "From",
];

/// True when `did` is one of C's scalar type names: an alias `core::ffi`,
/// `std::os::raw` or `libc` declares for a C type (`c_int`, `c_char`,
/// `size_t`). An alias is erased by typeck, so this is read off the HIR path
/// a signature spells, the one place the name survives.
fn is_c_type_alias(tcx: TyCtxt<'_>, did: DefId) -> bool {
    if !matches!(tcx.def_kind(did), DefKind::TyAlias) {
        return false;
    }
    match tcx.crate_name(did.krate).as_str() {
        "core" | "std" => tcx.opt_item_name(did).is_some_and(|n| n.as_str().starts_with("c_")),
        "libc" => true,
        _ => false,
    }
}

/// The C type names a HIR type spells, and the foreign-ABI fn pointers it
/// holds, counted once each: the mentions `fn.sig.of_which.c_type` counts.
struct CTypeMentions<'tcx> {
    tcx: TyCtxt<'tcx>,
    n: u64,
}

impl<'tcx> Visitor<'tcx> for CTypeMentions<'tcx> {
    fn visit_path(&mut self, path: &hir::Path<'tcx>, _id: hir::HirId) {
        if let Res::Def(_, did) = path.res {
            if is_c_type_alias(self.tcx, did) {
                self.n += 1;
            }
        }
        intravisit::walk_path(self, path);
    }

    fn visit_ty(&mut self, t: &'tcx hir::Ty<'tcx, hir::AmbigArg>) {
        if let hir::TyKind::FnPtr(f) = t.kind {
            if f.abi != ExternAbi::Rust {
                self.n += 1;
            }
        }
        intravisit::walk_ty(self, t);
            }
        }
        _ => {}
    }
}

/// Where the crate's declarations mention a `CCell` layout newtype
/// (`ty.ffibox.wrapper.as`) or the raw C type it covers (`ty.ffibox.sys.as`),
/// each in one arm by the innermost holder above it: borrowed or owned, by std
/// or by ffibox, or held by value with nothing above it. They sit under
/// `ty.ffibox`, since every one of them reads ffibox's convention and none is
/// emitted without the flag.
///
/// MENTIONS, not types. One cell is named in many places and it is the places
/// that are actionable, so a cell named in twenty signatures counts twenty
/// times and `--sites` lists them. The alternative, a type population, washes
/// the signal out: nearly every cell has an `as_ref`, so `self_in_ref_accessor`
/// would cover nearly every borrowed cell and the mentions that are NOT
/// sanctioned -- the ones worth reading -- would not be recoverable by
/// subtracting it.
///
/// `by_val` is the cell held as a value: no holder above the mention, so the
/// bytes are Rust-owned storage that moves with whatever holds it. A C pointer
/// retained into it dangles, and no owner runs the C destructor -- the cases
/// ffibox's `CBox` and `CVal` exist for.
fn count_cell_mentions(tcx: TyCtxt<'_>, ptr: &mut PtrTally, sites: &mut Sites) {
    let types = cell_types(tcx);
    if types.cells.is_empty() {
        return;
    }
    count_sys_types(tcx, ptr, sites, &types.cs);
    let evis = tcx.effective_visibilities(());
    let mut mentions: Vec<Mention> = Vec::new();

    for ld in tcx.hir_crate_items(()).definitions() {
        let did = ld.to_def_id();
        if !matches!(tcx.def_kind(did), DefKind::Struct | DefKind::Union)
            || in_generated_file(tcx, tcx.def_span(did))
        {
            continue;
        }
        let exported = did.as_local().is_some_and(|l| evis.is_exported(l));
        for f in tcx.adt_def(did).all_fields() {
            let ft = tcx.type_of(f.did).instantiate_identity().skip_norm_wip();
            let mut found = Vec::new();
            walk_shapes(tcx, ft, Shape::default(), &mut found);
            let reachable =
                exported && f.did.as_local().is_some_and(|l| evis.is_exported(l));
            let site = counter_site(tcx, tcx.def_span(f.did));
            for (did, shape) in found {
                mentions.push(Mention {
                    did,
                    shape,
                    field: true,
                    reachable,
                    self_in_ref_accessor: false,
                    self_in_trait_impl: false,
                    ref_forming: false,
                    site: site.clone(),
                });
            }
        }
    }

    // Signatures, over the same population `fn.*` counts: a foreign
    // declaration has no body, so it never reaches `hir_body_owners`, and the
    // C declarations in a `-sys` crate are not this crate's choices.
    for owner in tcx.hir_body_owners() {
        let did = owner.to_def_id();
